insert into public.site_settings (key, value) values ('general', '{"name":"Meriem Jaballah","email":"","phone":"","whatsapp":"","instagram":"","qrUrl":"","qrLabel":{"en":"Scan to Explore","fr":"Scannez pour découvrir","ar":"امسح الرمز للاكتشاف","tr":"Keşfetmek için tarayın"},"siteUrl":"https://portefilomariemproject.netlify.app"}'::jsonb) on conflict do nothing;
