insert into public.portfolio_sections (key, content, sort_order) values ('hero', '{"kicker":{"en":"Kids Animation • Children’s Sports • Dance Performance","fr":"Animation enfants • Sport pour enfants • Danse de scène","ar":"تنشيط الأطفال • رياضة الأطفال • عروض الرقص","tr":"Çocuk Animasyonu • Çocuk Sporları • Dans Gösterisi"},"headline":{"en":"Little Steps. Big Confidence. Unforgettable Moments.","fr":"Petits pas. Grande confiance. Des moments inoubliables.","ar":"خطوات صغيرة. ثقة كبيرة. لحظات لا تُنسى.","tr":"Küçük Adımlar. Büyük Özgüven. Unutulmaz Anlar."},"intro":{"en":"Creating joyful experiences through Kids Animation, Children’s Sports and Dance Performance.","fr":"Je crée des expériences joyeuses grâce à l’animation enfants, au sport pour enfants et à la danse de scène.","ar":"أصنع تجارب مليئة بالفرح من خلال تنشيط الأطفال ورياضة الأطفال وعروض الرقص.","tr":"Çocuk animasyonu, çocuk sporları ve dans gösterileriyle neşe dolu deneyimler yaratıyorum."}}'::jsonb, 0) on conflict do nothing;
insert into public.portfolio_sections (key, content, sort_order) values ('about', '{"title":{"en":"About Meriem","fr":"À propos de Meriem","ar":"نبذة عن مريم","tr":"Meriem Hakkında"},"body":{"en":"Energetic and caring professional with 6 years of experience in children’s animation, kids’ sports coaching and stage performance. Specialised in baby gymnastics, baby basketball and kids’ gymnastics, delivering safe and engaging sessions that develop motor skills, confidence and team spirit. Since 2024, performing LED and high-heels dance shows for international audiences in hotels and events. Patient, creative and reliable, communicating with children, parents and colleagues in Arabic, French and English.","fr":"Professionnelle énergique et bienveillante, avec 6 ans d’expérience en animation enfants, en coaching sportif pour enfants et en spectacle. Spécialisée en baby gym, baby basket et gymnastique enfants, j’anime des séances sûres et ludiques qui développent la motricité, la confiance et l’esprit d’équipe. Depuis 2024, je me produis dans des spectacles de danse LED et high heels devant un public international, dans des hôtels et des événements. Patiente, créative et fiable, je communique avec les enfants, les parents et mes collègues en arabe, en français et en anglais.","ar":"محترفة مفعمة بالطاقة والحنان، بخبرة 6 سنوات في تنشيط الأطفال وتدريب الرياضة للأطفال والعروض الفنية. متخصصة في جمباز الصغار وكرة السلة للصغار وجمباز الأطفال، أقدّم حصصًا آمنة وممتعة تنمّي المهارات الحركية والثقة وروح الفريق. منذ 2024 أقدّم عروض رقص LED والكعب العالي لجمهور دولي في الفنادق والفعاليات. صبورة ومبدعة وموثوقة، أتواصل مع الأطفال والأولياء والزملاء بالعربية والفرنسية والإنجليزية.","tr":"Çocuk animasyonu, çocuk spor koçluğu ve sahne performansında 6 yıllık deneyime sahip, enerjik ve şefkatli bir profesyonelim. Bebek jimnastiği, bebek basketbolu ve çocuk jimnastiğinde uzmanlaşarak motor becerileri, özgüveni ve takım ruhunu geliştiren güvenli ve eğlenceli dersler veriyorum. 2024’ten beri otellerde ve etkinliklerde uluslararası izleyicilere LED ve topuklu dans gösterileri sunuyorum. Sabırlı, yaratıcı ve güvenilirim; çocuklar, ebeveynler ve meslektaşlarla Arapça, Fransızca ve İngilizce iletişim kuruyorum."},"location":{"en":"Tunisia","fr":"Tunisie","ar":"تونس","tr":"Tunus"},"nationality":{"en":"Tunisian","fr":"Tunisienne","ar":"تونسية","tr":"Tunuslu"},"relocation":{"en":"Hotels • Resorts • Kids clubs • Events","fr":"Hôtels • Resorts • Clubs enfants • Événements","ar":"فنادق • منتجعات • نوادي أطفال • فعاليات","tr":"Oteller • Tatil köyleri • Çocuk kulüpleri • Etkinlikler"},"stats":[{"value":6,"suffix":"+","label":{"en":"Years Experience","fr":"Ans d’expérience","ar":"سنوات خبرة","tr":"Yıllık Deneyim"}},{"value":4,"suffix":"","label":{"en":"Languages","fr":"Langues","ar":"لغات","tr":"Dil"}},{"value":3,"suffix":"","label":{"en":"Kids’ Sports","fr":"Sports enfants","ar":"رياضات للأطفال","tr":"Çocuk Sporu"}}]}'::jsonb, 1) on conflict do nothing;
insert into public.portfolio_sections (key, content, sort_order) values ('dance', '{"intro":{"en":"LED, high-heels and themed dance shows for international guests in hotels and private events — synchronized routines, quick costume changes and strong stage presence.","fr":"Spectacles de danse LED, high heels et à thème pour une clientèle internationale, dans des hôtels et des événements privés : chorégraphies synchronisées, changements de costume rapides et forte présence scénique.","ar":"عروض رقص LED والكعب العالي وعروض بطابع خاص لضيوف دوليين في الفنادق والفعاليات الخاصة — رقصات متناسقة وتبديل سريع للأزياء وحضور قوي على المسرح.","tr":"Otellerde ve özel etkinliklerde uluslararası misafirler için LED, topuklu ve temalı dans gösterileri — senkronize koreografiler, hızlı kostüm değişimleri ve güçlü sahne varlığı."}}'::jsonb, 2) on conflict do nothing;
insert into public.portfolio_sections (key, content, sort_order) values ('contact', '{"intro":{"en":"Hotels, resorts, kids clubs, sports academies or event organisers: let’s create joyful moments together.","fr":"Hôtels, resorts, clubs enfants, académies sportives ou organisateurs d’événements : créons ensemble des moments joyeux.","ar":"فنادق ومنتجعات ونوادي أطفال وأكاديميات رياضية ومنظمو فعاليات: لنصنع معًا لحظات مليئة بالفرح.","tr":"Oteller, tatil köyleri, çocuk kulüpleri, spor akademileri veya etkinlik organizatörleri: birlikte neşeli anlar yaratalım."}}'::jsonb, 3) on conflict do nothing;
insert into public.experiences (id, period, sort_order, visible, role, company, location, bullets) values ('kids-animator', '2020 – Mar 2024', 1, true, '{"en":"Kids Animator & Baby Sports Coach","fr":"Animatrice enfants & coach baby sport","ar":"منشّطة أطفال ومدربة رياضة للصغار","tr":"Çocuk Animatörü ve Bebek Sporları Koçu"}'::jsonb, '{"en":"Baby Gymnastics • Baby Basketball • Kids Animation","fr":"Baby gym • Baby basket • Animation enfants","ar":"جمباز الصغار • كرة السلة للصغار • تنشيط الأطفال","tr":"Bebek Jimnastiği • Bebek Basketbolu • Çocuk Animasyonu"}'::jsonb, '{"en":"Tunisia","fr":"Tunisie","ar":"تونس","tr":"Tunus"}'::jsonb, '{"en":["Designed and ran fun activities, games and themed events for children of different ages","Coached baby gymnastics and baby basketball, developing motor skills, rhythm and teamwork","Ensured children’s safety and wellbeing, supervising groups with patience and positive discipline","Animated birthdays, parties and celebrations with music, dance and games","Kept parents informed and reassured"],"fr":["Conception et animation d’activités, de jeux et d’événements à thème pour des enfants de tous âges","Coaching en baby gym et baby basket pour développer la motricité, le rythme et l’esprit d’équipe","Sécurité et bien-être des enfants, encadrement des groupes avec patience et discipline positive","Animation d’anniversaires, de fêtes et de célébrations avec musique, danse et jeux","Communication régulière et rassurante avec les parents"],"ar":["تصميم وتنشيط أنشطة وألعاب وفعاليات بطابع خاص لأطفال من مختلف الأعمار","تدريب جمباز الصغار وكرة السلة للصغار لتنمية المهارات الحركية والإيقاع والعمل الجماعي","ضمان سلامة الأطفال وراحتهم والإشراف على المجموعات بصبر وانضباط إيجابي","تنشيط أعياد الميلاد والحفلات والاحتفالات بالموسيقى والرقص والألعاب","إبقاء الأولياء على اطلاع وطمأنتهم"],"tr":["Farklı yaşlardaki çocuklar için eğlenceli aktiviteler, oyunlar ve temalı etkinlikler tasarladı ve yürüttü","Bebek jimnastiği ve bebek basketbolu koçluğuyla motor becerileri, ritmi ve takım çalışmasını geliştirdi","Grupları sabır ve pozitif disiplinle yöneterek çocukların güvenliğini ve iyiliğini sağladı","Doğum günlerini, partileri ve kutlamaları müzik, dans ve oyunlarla canlandırdı","Ebeveynleri bilgilendirdi ve güven verdi"]}'::jsonb) on conflict do nothing;
insert into public.experiences (id, period, sort_order, visible, role, company, location, bullets) values ('bouabdeli', '2023 – Mar 2024', 2, true, '{"en":"Kids Gymnastics Coach","fr":"Coach de gymnastique enfants","ar":"مدربة جمباز للأطفال","tr":"Çocuk Jimnastiği Koçu"}'::jsonb, '{"en":"Bouabdeli","fr":"Bouabdeli","ar":"بوعبدلي","tr":"Bouabdeli"}'::jsonb, '{"en":"Tunisia","fr":"Tunisie","ar":"تونس","tr":"Tunus"}'::jsonb, '{"en":["Planned and led kids’ gymnastics classes focused on balance, flexibility, coordination and strength","Taught age-appropriate techniques step by step","Applied safe spotting and correct use of mats and equipment","Tracked each child’s progress and adapted exercises to individual levels","Prepared children for demonstrations and end-of-year shows, building their confidence"],"fr":["Préparation et animation de cours de gymnastique enfants axés sur l’équilibre, la souplesse, la coordination et la force","Enseignement progressif de techniques adaptées à l’âge","Parade sécurisée et bon usage des tapis et du matériel","Suivi des progrès de chaque enfant et adaptation des exercices à son niveau","Préparation aux démonstrations et galas de fin d’année pour renforcer leur confiance"],"ar":["تخطيط وتقديم حصص جمباز للأطفال تركّز على التوازن والمرونة والتناسق والقوة","تعليم تقنيات مناسبة للعمر خطوة بخطوة","تطبيق المساندة الآمنة والاستخدام الصحيح للحُصُر والمعدات","متابعة تقدّم كل طفل وتكييف التمارين مع مستواه","تحضير الأطفال للعروض واحتفالات نهاية السنة لتعزيز ثقتهم"],"tr":["Denge, esneklik, koordinasyon ve güce odaklanan çocuk jimnastiği derslerini planladı ve yönetti","Yaşa uygun teknikleri adım adım öğretti","Güvenli spotlama yaptı, minder ve ekipmanların doğru kullanımını sağladı","Her çocuğun gelişimini takip ederek egzersizleri seviyesine göre uyarladı","Çocukları gösterilere ve yıl sonu şovlarına hazırlayarak özgüvenlerini geliştirdi"]}'::jsonb) on conflict do nothing;
insert into public.experiences (id, period, sort_order, visible, role, company, location, bullets) values ('dance-performer', '2024 – 2026', 3, true, '{"en":"Dance Performer — LED & High-Heels Shows","fr":"Danseuse — spectacles LED & high heels","ar":"راقصة — عروض LED والكعب العالي","tr":"Dansçı — LED ve Topuklu Dans Gösterileri"}'::jsonb, '{"en":"Hotels, Events & Entertainment Shows","fr":"Hôtels, événements & spectacles","ar":"فنادق وفعاليات وعروض ترفيهية","tr":"Oteller, Etkinlikler ve Eğlence Gösterileri"}'::jsonb, '{"en":"International audiences","fr":"Public international","ar":"جمهور دولي","tr":"Uluslararası izleyici"}'::jsonb, '{"en":["Performed LED, high-heels and themed dance shows for international guests in hotels and private events","Learned and mastered new choreographies quickly","Delivered synchronized routines within a professional team","Handled LED costumes and props carefully, with quick changes between show segments","Maintained strong stage presence, punctuality and professional presentation"],"fr":["Spectacles de danse LED, high heels et à thème pour une clientèle internationale, en hôtel et lors d’événements privés","Apprentissage et maîtrise rapides de nouvelles chorégraphies","Routines synchronisées au sein d’une équipe professionnelle","Soin des costumes et accessoires LED, changements rapides entre les tableaux","Forte présence scénique, ponctualité et présentation professionnelle"],"ar":["تقديم عروض رقص LED والكعب العالي وعروض بطابع خاص لضيوف دوليين في الفنادق والفعاليات الخاصة","تعلّم الرقصات الجديدة وإتقانها بسرعة","أداء رقصات متناسقة ضمن فريق محترف","العناية بأزياء وأكسسوارات LED وتبديل الأزياء بسرعة بين فقرات العرض","حضور قوي على المسرح والتزام بالمواعيد ومظهر مهني"],"tr":["Otellerde ve özel etkinliklerde uluslararası misafirler için LED, topuklu ve temalı dans gösterileri sundu","Yeni koreografileri hızla öğrenip ustalaştı","Profesyonel bir ekip içinde senkronize rutinler sergiledi","LED kostüm ve aksesuarları özenle kullandı, bölümler arasında hızlı kostüm değişimleri yaptı","Güçlü sahne varlığı, dakiklik ve profesyonel görünüm sergiledi"]}'::jsonb) on conflict do nothing;
insert into public.services (id, image, sort_order, visible, title, description, tags) values ('animation', '/media/illus/kids-group.webp', 1, true, '{"en":"Kids Animation & Entertainment","fr":"Animation & divertissement enfants","ar":"تنشيط الأطفال والترفيه","tr":"Çocuk Animasyonu ve Eğlence"}'::jsonb, '{"en":"Themed games, mini-disco, birthdays and celebrations that keep every child engaged and safe.","fr":"Jeux à thème, mini-disco, anniversaires et fêtes où chaque enfant s’amuse en toute sécurité.","ar":"ألعاب بطابع خاص وميني ديسكو وأعياد ميلاد واحتفالات يشارك فيها كل طفل بأمان.","tr":"Her çocuğun güvenle eğlendiği temalı oyunlar, mini disko, doğum günleri ve kutlamalar."}'::jsonb, '{"en":["Activity planning","Mini-disco","Group management"],"fr":["Planification d’activités","Mini-disco","Gestion de groupe"],"ar":["تخطيط الأنشطة","ميني ديسكو","إدارة المجموعات"],"tr":["Aktivite planlama","Mini disko","Grup yönetimi"]}'::jsonb) on conflict do nothing;
insert into public.services (id, image, sort_order, visible, title, description, tags) values ('baby-gym', '/media/illus/baby-gym.webp', 2, true, '{"en":"Baby Gymnastics & Baby Sports","fr":"Baby gym & baby sport","ar":"جمباز الصغار ورياضة الصغار","tr":"Bebek Jimnastiği ve Bebek Sporları"}'::jsonb, '{"en":"Playful first movements on safe equipment: motor skills, rhythm and confidence from the very first steps.","fr":"Premiers mouvements ludiques sur du matériel sécurisé : motricité, rythme et confiance dès les premiers pas.","ar":"حركات أولى ممتعة على معدات آمنة: مهارات حركية وإيقاع وثقة منذ الخطوات الأولى.","tr":"Güvenli ekipmanlarla eğlenceli ilk hareketler: ilk adımlardan itibaren motor beceri, ritim ve özgüven."}'::jsonb, '{"en":["Baby gymnastics","Baby basketball","Child safety"],"fr":["Baby gym","Baby basket","Sécurité des enfants"],"ar":["جمباز الصغار","كرة السلة للصغار","سلامة الأطفال"],"tr":["Bebek jimnastiği","Bebek basketbolu","Çocuk güvenliği"]}'::jsonb) on conflict do nothing;
insert into public.services (id, image, sort_order, visible, title, description, tags) values ('kids-coaching', '/media/illus/kids-gym-group.webp', 3, true, '{"en":"Children’s Gymnastics & Sports Coaching","fr":"Gymnastique & coaching sportif enfants","ar":"جمباز الأطفال والتدريب الرياضي","tr":"Çocuk Jimnastiği ve Spor Koçluğu"}'::jsonb, '{"en":"Balance, flexibility, coordination and strength, taught step by step with safe spotting.","fr":"Équilibre, souplesse, coordination et force, enseignés pas à pas avec une parade sécurisée.","ar":"التوازن والمرونة والتناسق والقوة، تُعلَّم خطوة بخطوة مع مساندة آمنة.","tr":"Denge, esneklik, koordinasyon ve güç; güvenli spotlama ile adım adım öğretilir."}'::jsonb, '{"en":["Kids gymnastics","Progress tracking","Shows & demos"],"fr":["Gymnastique enfants","Suivi des progrès","Galas & démonstrations"],"ar":["جمباز الأطفال","متابعة التقدّم","عروض واستعراضات"],"tr":["Çocuk jimnastiği","Gelişim takibi","Gösteriler"]}'::jsonb) on conflict do nothing;
insert into public.services (id, image, sort_order, visible, title, description, tags) values ('dance', '/media/illus/stage-led.webp', 4, true, '{"en":"Dance & LED Performance","fr":"Danse & spectacles LED","ar":"الرقص وعروض LED","tr":"Dans ve LED Gösterileri"}'::jsonb, '{"en":"LED, high-heels and themed shows for hotels and events, with fast choreography learning and stage presence.","fr":"Spectacles LED, high heels et à thème pour hôtels et événements, avec apprentissage rapide et présence scénique.","ar":"عروض LED والكعب العالي وعروض بطابع خاص للفنادق والفعاليات، مع تعلّم سريع للرقصات وحضور مسرحي.","tr":"Oteller ve etkinlikler için LED, topuklu ve temalı gösteriler; hızlı koreografi öğrenimi ve sahne varlığı."}'::jsonb, '{"en":["LED shows","High-heels","Choreography"],"fr":["Spectacles LED","High heels","Chorégraphie"],"ar":["عروض LED","الكعب العالي","تصميم الرقصات"],"tr":["LED gösterileri","Topuklu dans","Koreografi"]}'::jsonb) on conflict do nothing;
